import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { NotificationService } from '../services/notification.service';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [
    FormsModule,
    CommonModule
  ],
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  email = '';
  password = '';

  constructor(
    private authService: AuthService,
    private router: Router,
    private notificationService: NotificationService
  ) {}

  login(): void {
    this.authService.login(this.email, this.password).subscribe({
      next: () => {
        this.router.navigate(['/']);
        this.notificationService.success('Login successful!');
      },
      error: (err) => {
        console.error('Login failed', err);
        this.notificationService.error('Login failed. Please check your credentials.');
      }
    });
  }
}
<body class="bg-neutral-100" style='font-family: "Plus Jakarta Sans", "Noto Sans", sans-serif;'>
<div class="relative flex size-full min-h-screen flex-col group/design-root overflow-x-hidden">
  <div class="layout-container flex h-full grow flex-col">
    <main class="flex flex-1 items-center justify-center py-8 px-4 sm:px-6 lg:px-8">
      <div class="w-full max-w-md space-y-8">
        <div class="bg-white p-8 shadow-xl rounded-xl">
          <h2 class="text-center text-3xl font-extrabold text-neutral-800 mb-2">Welcome back</h2>
          <p class="text-center text-sm text-neutral-600 mb-8">
            Enter your credentials to access your account.
          </p>
          <form class="space-y-6" (ngSubmit)="login()">
            <div>
              <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="email">Email address</label>
              <input autocomplete="email" class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="email" name="email" placeholder="you@example.com" required="" type="email" [(ngModel)]="email"/>
            </div>
            <div>
              <div class="flex items-center justify-between">
                <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="password">Password</label>
                <a class="text-sm font-medium text-[#141414] hover:text-neutral-700 link-subtle" href="#">Forgot your password?</a>
              </div>
              <input autocomplete="current-password" class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="password" name="password" placeholder="••••••••" required="" type="password" [(ngModel)]="password"/>
            </div>
            <div>
              <button class="flex min-w-[120px] max-w-[480px] cursor-pointer items-center justify-center overflow-hidden rounded-lg h-12 px-6 @[480px]:h-14 @[480px]:px-8 bg-[#eb6c28] text-white text-base font-bold leading-normal tracking-[0.015em] @[480px]:text-lg @[480px]:font-bold @[480px]:leading-normal @[480px]:tracking-[0.015em] hover:bg-[#d95f21] transition-colors shadow-md" type="submit">
                Log in
              </button>
            </div>
          </form>
          <p class="mt-8 text-center text-sm text-neutral-500">
            Don't have an account?
            <a class="font-medium text-[#141414] hover:text-neutral-700 link-subtle" routerLink="/signup">Sign up</a>
          </p>
        </div>
      </div>
    </main>
  </div>
</div>
</body>
